import { NextRequest, NextResponse } from 'next/server'
import { fetchFreelancerJobs } from '@/lib/apis/freelancer-api'
import { fetchFiverrJobs } from '@/lib/apis/fiverr-api'
import { UnifiedJob } from '@/lib/types/job-types'

export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams
  const query = searchParams.get('q') || ''
  const source = searchParams.get('source') || 'all'
  const limit = parseInt(searchParams.get('limit') || '20')

  try {
    const jobs: UnifiedJob[] = []

    // Fetch from Freelancer API
    if (source === 'all' || source === 'freelancer') {
      try {
        const freelancerJobs = await fetchFreelancerJobs({ query, limit })
        jobs.push(...freelancerJobs)
      } catch (error) {
        console.error('Freelancer API error:', error)
      }
    }

    // Fetch from Fiverr
    if (source === 'all' || source === 'fiverr') {
      try {
        const fiverrJobs = await fetchFiverrJobs({ query, limit })
        jobs.push(...fiverrJobs)
      } catch (error) {
        console.error('Fiverr API error:', error)
      }
    }

    // Sort by posted date (newest first)
    jobs.sort((a, b) => b.posted.getTime() - a.posted.getTime())

    return NextResponse.json({
      success: true,
      data: jobs,
      count: jobs.length,
      sources: {
        freelancer: source === 'all' || source === 'freelancer',
        fiverr: source === 'all' || source === 'fiverr'
      }
    })
  } catch (error) {
    console.error('Jobs API error:', error)
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to fetch jobs',
        message: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    )
  }
}
